{"aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "config": {
    "kibana": {
      "hideWarnings": true
    },
    "text": {
      "baseline": "middle",
      "fontSize": 12
    }
  },
  "data": [
    {
      "format": {
        "property": "aggregations.top.buckets"
      },
      "name": "src",
      "transform": [
        {
          "as": "value",
          "expr": "datum.key",
          "type": "formula"
        },
        {
          "as": "alerts",
          "expr": "datum.doc_count",
          "type": "formula"
        }
      ],
      "url": {
        "body": {
          "aggs": {
            "top": {
              "terms": {
                "field": "data.transaction.request.uri",
                "size": 20
              }
            }
          },
          "query": {
            "bool": {
              "filter": [
                "%dashboard_context-filter_clause%"
              ],
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "timestamp": {
                      "%timefilter%": true
                    }
                  }
                },
                {
                  "query_string": {
                    "analyze_wildcard": true,
                    "query": "rule.id:[133500 TO 133599] AND rule.id:/[0-9]{6}/"
                  }
                }
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ]
            }
          },
          "size": 0
        },
        "index": "wazuh-alerts-*"
      }
    },
    {
      "name": "rows",
      "source": "src",
      "transform": [
        {
          "as": [
            "row0"
          ],
          "ops": [
            "row_number"
          ],
          "sort": {
            "field": {
              "signal": "sortField"
            },
            "order": {
              "signal": "sortDesc ? 'descending' : 'ascending'"
            }
          },
          "type": "window"
        },
        {
          "as": "row",
          "expr": "datum.row0 - 1",
          "type": "formula"
        },
        {
          "expr": "datum.row < floor((height - 20) / 20)",
          "type": "filter"
        }
      ]
    },
    {
      "name": "head",
      "values": [
        {
          "align": "left",
          "key": "value",
          "label": "請求網址 (data.transaction.request.uri)",
          "num": false,
          "right": false,
          "x": 0
        },
        {
          "align": "right",
          "key": "alerts",
          "label": "告警",
          "num": true,
          "right": true,
          "x": 0
        }
      ]
    }
  ],
  "marks": [
    {
      "encode": {
        "update": {
          "align": {
            "field": "align"
          },
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#69707D"
          },
          "fontWeight": {
            "value": "bold"
          },
          "text": {
            "signal": "datum.label + (datum.key === sortField ? (sortDesc ? ' ▼' : ' ▲') : '')"
          },
          "tooltip": {
            "value": "點擊以排序"
          },
          "x": {
            "signal": "datum.right ? width - datum.x : datum.x"
          },
          "y": {
            "value": 14.0
          }
        }
      },
      "from": {
        "data": "head"
      },
      "name": "jtHead",
      "type": "text"
    },
    {
      "encode": {
        "update": {
          "stroke": {
            "value": "#D3DAE6"
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "value": 20
          },
          "y2": {
            "value": 20
          }
        }
      },
      "type": "rule"
    },
    {
      "encode": {
        "update": {
          "align": {
            "value": "left"
          },
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#006BB4"
          },
          "limit": {
            "signal": "width - 90"
          },
          "text": {
            "field": "value"
          },
          "tooltip": {
            "signal": "'點擊以篩選' + ': ' + datum.value"
          },
          "x": {
            "value": 0
          },
          "y": {
            "signal": "(datum.row + 0.7) * 20 + 20"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "name": "jtCell_value",
      "type": "text"
    },
    {
      "encode": {
        "update": {
          "align": {
            "value": "right"
          },
          "text": {
            "signal": "format(datum.alerts, ',')"
          },
          "x": {
            "signal": "width - 0"
          },
          "y": {
            "signal": "(datum.row + 0.7) * 20 + 20"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "text"
    }
  ],
  "padding": {
    "bottom": 2,
    "left": 4,
    "right": 4,
    "top": 2
  },
  "signals": [
    {
      "name": "sortBy",
      "on": [
        {
          "events": "@jtHead:click",
          "update": "{field: datum.key, desc: datum.key === sortBy.field ? !sortBy.desc : datum.num}"
        }
      ],
      "value": {
        "desc": true,
        "field": "alerts"
      }
    },
    {
      "name": "sortField",
      "update": "sortBy.field"
    },
    {
      "name": "sortDesc",
      "update": "sortBy.desc"
    },
    {
      "name": "jtCell_valueFilter",
      "on": [
        {
          "events": "@jtCell_value:click",
          "update": "datum.value === '-' ? null : opensearchDashboardsAddFilter({'match_phrase': {\"data.transaction.request.uri\": datum.value}}, \"wazuh-alerts-*\", \"data.transaction.request.uri\" + ': ' + datum.value)"
        }
      ],
      "value": null
    }
  ]
}"},"title":"jt-modsecurity · 請求網址","type":"vega"}

